#!/usr/bin/env bash
# Delete the benchmark data (data/bench/) after explicit confirmation.
#
# Removes the shards, the read-benchmark copies, Spark's scratch space and the temporary files.
# Nothing else is touched: the pipeline data in data/raw and data/processed, the database and
# the object store stay. Everything deleted here is regenerated by `make bench-data`.
#
# Compatible with macOS /bin/bash 3.2.
set -euo pipefail

readonly TARGET="data/bench"
readonly CONFIRM_WORD="DELETE"

project_root="$(cd "$(dirname "$0")/.." && pwd -P)"
cd "$project_root"

if [ ! -d "$TARGET" ]; then
    echo "${TARGET} does not exist; nothing to delete."
    exit 0
fi

size="$(du -sh "$TARGET" 2>/dev/null | cut -f1)"
echo "=================================================================="
echo " WARNING: THIS DELETES THE BENCHMARK DATA"
echo "=================================================================="
echo " Directory: ${project_root}/${TARGET} (${size:-unknown size})"
echo " Shards, read-benchmark copies, Spark scratch space and temp files."
echo " Regenerate with: make bench-data SHARDS=n"
echo " The pipeline data, the database and the object store are not touched."
echo "=================================================================="

if [ ! -t 0 ]; then
    echo "Aborted: no interactive terminal to confirm. Nothing was deleted." >&2
    exit 1
fi

printf 'Type %s to confirm (anything else aborts): ' "$CONFIRM_WORD"
answer=""
read -r answer || true
if [ "$answer" != "$CONFIRM_WORD" ]; then
    echo "Aborted. Nothing was deleted." >&2
    exit 1
fi

rm -rf "${project_root:?}/${TARGET}"
echo "${TARGET} deleted."
